from pathlib import Path
import json, html

root = Path(__file__).parent
for folder in ['assets/css', 'assets/js', 'assets/img']:
    (root / folder).mkdir(parents=True, exist_ok=True)
D = {'ar': {}, 'en': {}}
def t(key, ar, en, tag='span', attrs=''):
    D['ar'][key], D['en'][key] = ar, en
    return f'<{tag} data-i18n="{key}" {attrs}>{html.escape(ar)}</{tag}>'
def img(name, ar, en, width=800, height=600, eager=False, cls=''):
    key = 'alt.' + name
    D['ar'][key], D['en'][key] = ar, en
    return f'<img class="{cls}" src="assets/img/{name}.webp" alt="{ar}" data-i18n-alt="{key}" width="{width}" height="{height}" {"fetchpriority=high" if eager else "loading=lazy"} decoding="async">'
def heading(key, kick, kicken, title, titleen, sub='', suben=''):
    return '<div class="section-head reveal">' + t(key+'.kick',kick,kicken,attrs='class="section-kicker"') + t(key+'.title',title,titleen,'h2') + '<div class="divider"></div>' + (t(key+'.sub',sub,suben,'p') if sub else '') + '</div>'
