def head(title,description,page=''):
    return f'''<!doctype html>
<html lang="ar" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>{title}</title><meta name="description" content="{description}"><meta name="theme-color" content="#030407"><link rel="canonical" href="https://vgo.almobarmg.com/{page}"><meta property="og:type" content="website"><meta property="og:title" content="{title}"><meta property="og:description" content="{description}"><meta property="og:url" content="https://vgo.almobarmg.com/{page}"><meta property="og:locale" content="ar_EG"><meta property="og:locale:alternate" content="en_US"><meta property="og:image" content="https://vgo.almobarmg.com/assets/img/og-captain.jpg"><meta property="og:image:width" content="1200"><meta property="og:image:height" content="630"><meta property="og:image:alt" content="V.Go Captain"><meta name="twitter:card" content="summary_large_image"><link rel="icon" type="image/png" href="assets/img/favicon.png"><link rel="apple-touch-icon" href="assets/img/captain-icon.png"><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=Cairo:wght@400;600;700;800;900&family=Poppins:wght@400;500;600;700;800&display=swap" rel="stylesheet"><link rel="stylesheet" href="assets/css/styles.css?v=20261025d"><script src="assets/js/config.js?v=20261025d" defer></script><script src="assets/js/i18n.js?v=20261025d" defer></script><script src="assets/js/main.js" defer></script></head>'''
D['ar']['meta.title']='V.Go Captain | إنت الكابتن والطريق قدّامك'
D['en']['meta.title']='V.Go Captain | Your next ride starts here'
D['ar']['meta.description']='تطبيق V.Go للكباتن في مصر. استقبل طلبات الرحلات، استخدم الملاحة، وتابع أرباحك وحساباتك ومستنداتك. حمّل التطبيق لأندرويد وآيفون.'
D['en']['meta.description']='V.Go’s captain app in Egypt. Receive trip requests, navigate, and track earnings, finances and verification. Download for Android and iPhone.'
index=head(D['ar']['meta.title'],D['ar']['meta.description'])+'<body data-page="home">'+t('skip','تخطّي للمحتوى','Skip to content','a','class="skip-link" href="#main"')+nav+'<main id="main">'+hero+why+features+steps+finance+faq+cta+'</main>'+footer+modal+'<noscript><p class="noscript">لتفعيل Google Play، شغّل JavaScript. يمكنك استخدام App Store مباشرةً. Enable JavaScript for Play activation, or use the App Store link.</p></noscript><script src="https://accounts.google.com/gsi/client" async defer></script><script src="assets/js/store-activate.js?v=20261025d" defer></script></body></html>'
