privacy=head('سياسة الخصوصية | V.Go Captain','كيف يستخدم V.Go Captain بيانات الحساب والموقع والمستندات والحسابات المالية.','privacy.html')+'<body data-page="privacy"><header class="navbar"><div class="container nav-inner">'+brand+langs+'</div></header><main class="privacy-wrap"><header class="privacy-header">'+t('privacy.title','سياسة الخصوصية','Privacy policy','h1')+t('privacy.date','V.Go Captain · آخر تحديث: ١٧ أكتوبر ٢٠٢٦','V.Go Captain · Last updated: 17 October 2026','p','class="small-note"')+'</header>'+t('privacy.intro','توضح هذه الصفحة أنواع البيانات المستخدمة لتشغيل V.Go Captain وموقعه، والغرض منها، والخيارات المتاحة لك. بعض الوظائف تعتمد على حالة حسابك والأذونات التي تمنحها.','This page explains the types of data used to operate V.Go Captain and its website, their purposes, and your choices. Some functions depend on your account status and the permissions you grant.','p')
policies=[
('بيانات الحساب','Account details','تشمل بيانات التسجيل الاسم ورقم الهاتف والبريد الإلكتروني وبيانات الملف الشخصي والمركبة التي تقدمها. تُستخدم لإنشاء الحساب، والتواصل المرتبط بالخدمة، وتشغيل حساب الكابتن.','Registration includes your name, phone number, email, and the profile and vehicle details you provide. These support account creation, service communications and captain account operation.'),
('الموقع أثناء العمل والرحلات','Location while online and on trips','يستخدم التطبيق موقع الجهاز عند إتاحتك للرحلات وأثناء الرحلة لتحديث موقع الكابتن، وتحديد نقطة الركوب، والملاحة ومتابعة الرحلة. قد تستمر تحديثات الموقع في الخلفية أثناء هذه الوظائف بحسب أذونات الجهاز. قد يُستخدم الموقع أيضًا لعرض موقعك على الخريطة عند فتحها. يمكنك إدارة الإذن من إعدادات الهاتف؛ تعطيله قد يمنع استقبال الرحلات أو الملاحة.','The app uses device location while you are online and during a trip to update captain position, locate pickup, navigate and track the trip. Location updates may continue in the background during these functions depending on device permissions. Location may also centre the map when opened. Manage permission in phone settings; disabling it may prevent requests or navigation.'),
('مستندات التحقق والصور','Verification documents and photos','قد ترفع صورتك الشخصية وصور البطاقة ورخص القيادة والمركبة ومستندات إضافية يطلبها التطبيق. تُستخدم للتحقق ومراجعة أهلية الحساب ومتابعة صلاحية المستندات. يُستخدم الوصول للكاميرا أو الصور عند اختيارك التقاط أو رفع صورة.','You may upload your photo, ID, driving and vehicle licences, and additional documents requested in the app. These support verification, account eligibility reviews and document validity checks. Camera or photo access is used when you choose to capture or upload an image.'),
('الرحلات والأرباح والتحصيل','Trips, earnings and collection','تُستخدم تفاصيل الرحلات وحالتها وطريقة الدفع والأجرة والعمولة والرصيد والمستحقات لإدارة الرحلات والحسابات. قد تشمل بيانات التحصيل قيمة التحويل وحساب المرسل أو هاتفه والحساب المستلم وحالة التأكيد. وتُستخدم بيانات الصرف التي تقدمها لإدارة مستحقاتك.','Trip details, status, payment method, fares, commission, balance and amounts due support trip and financial management. Collection data may include transfer amount, sender account or phone, destination account and confirmation status. Payout details you provide support management of amounts owed to you.'),
('الإشعارات وبيانات التشغيل','Notifications and operational data','تُستخدم رموز الإشعارات لإرسال تنبيهات الرحلات والحساب. وقد تُعالج بيانات تقنية عن الجهاز والأعطال للمساعدة في تشخيص مشاكل التطبيق. رسائل الدعم التي ترسلها تُستخدم لمتابعة استفسارك.','Notification tokens support trip and account alerts. Technical device and crash information may be processed to help diagnose app issues. Support messages you send are used to follow up on your request.'),
('مشاركة البيانات لتقديم الخدمة','Sharing to provide the service','تُعرض معلومات الرحلة والموقع وبيانات التواصل اللازمة للأطراف المعنية بالرحلة. وتُعالج البيانات اللازمة بواسطة خدمات الخرائط والإشعارات وتسجيل الدخول والدفع والاستضافة المستخدمة لتشغيل الخدمة، وبواسطة فريق التشغيل للمراجعة والدعم.','Trip, location and necessary contact information are shown to the parties involved in a trip. Relevant data is processed by the map, notification, sign-in, payment and hosting services used to operate the service, and by the operations team for review and support.'),
('الموقع وتفعيل Google Play', 'Website and Google Play activation', 'تفعيل Google Play خاص بتطبيق V.Go Captain فقط؛ تحميل تطبيق الركاب لا يحتاجه. بعد اختيار حساب Google وتأكيده، يُرسل رمز تسجيل الدخول من Google إلى خادم V.Go لإتاحة التحميل، ويُستخدم بريد الحساب لمتابعة حالة الطلب. لا يطلب الموقع كلمة مرور Google. يُحفظ اختيار اللغة فقط محليًا في المتصفح. يتم تحميل الخطوط من Google Fonts، وخدمة اختيار الحساب من Google.', 'Google Play activation applies only to V.Go Captain; V.Go rider downloads do not require it. After you choose and confirm a Google account, its Google sign-in token is sent to V.Go’s server to enable the download, and the account email is used to check the request status. The site does not ask for your Google password. Only the language preference is saved locally in the browser. Fonts load from Google Fonts, and Google provides the account picker.'),
('الاحتفاظ والخيارات المتاحة لك','Retention and your choices','يختلف الاحتفاظ بالبيانات بحسب الحاجة لتشغيل الحساب والرحلات ومراجعة المعاملات والالتزامات المعمول بها؛ لا تحدد هذه الصفحة مدة موحدة لكل البيانات. يمكنك تعديل بياناتك المتاحة في التطبيق وإدارة أذونات الموقع والصور والإشعارات من الهاتف، والتواصل مع الدعم لطلب الوصول أو التصحيح أو الحذف.','Retention depends on account and trip operation, transaction review and applicable obligations; this page does not specify one retention period for all data. You can edit available profile details, manage location, photo and notification permissions on your phone, and contact support to request access, correction or deletion.')]
for i,(title,en,body,bodyen) in enumerate(policies):
    privacy+='<section class="privacy-card">'+t(f'privacy.{i}.title',title,en,'h2')+t(f'privacy.{i}.body',body,bodyen,'p')+'</section>'
privacy+='<section class="privacy-card">'+t('privacy.contact','تواصل بخصوص بياناتك','Contact about your data','h2')+t('privacy.support','استخدم قسم الدعم الفني داخل V.Go Captain وأوضح طلبك المتعلق بالبيانات.','Use the Support section inside V.Go Captain and describe your data request.','p')+'<a id="privacyEmail" hidden></a></section>'+t('privacy.back','العودة إلى V.Go Captain','Back to V.Go Captain','a','class="button outline" href="index.html"')+'</main>'+footer+'</body></html>'
(root/'privacy.html').write_text(privacy,encoding='utf-8')
(root/'assets/js/i18n.js').write_text('/* Arabic-first copy and image descriptions. */\nwindow.VGO_DICTIONARY = '+json.dumps(D,ensure_ascii=False,indent=2)+';\n'+'''(function () {
  'use strict';
  var lang = 'ar';
  try { if (localStorage.getItem('vgo-language') === 'en') lang = 'en'; } catch (_) {}
  function apply(next) {
    lang = next === 'en' ? 'en' : 'ar';
    var d = window.VGO_DICTIONARY[lang];
    document.documentElement.lang = lang;
    document.documentElement.dir = lang === 'ar' ? 'rtl' : 'ltr';
    document.querySelectorAll('[data-i18n]').forEach(function (el) { if (d[el.dataset.i18n] !== undefined) el.textContent = d[el.dataset.i18n]; });
    document.querySelectorAll('[data-i18n-alt]').forEach(function (el) { el.alt = d[el.dataset.i18nAlt] || ''; });
    document.querySelectorAll('[data-lang-btn]').forEach(function (btn) { btn.setAttribute('aria-pressed', String(btn.dataset.langBtn === lang)); });
    var privacy = document.body.dataset.page === 'privacy';
    document.title = privacy ? d['privacy.title'] + ' | V.Go Captain' : d['meta.title'];
    if (!privacy) {
      document.querySelector('meta[name="description"]').content = d['meta.description'];
      document.querySelector('meta[property="og:title"]').content = d['meta.title'];
      document.querySelector('meta[property="og:description"]').content = d['meta.description'];
    }
    document.querySelector('meta[property="og:locale"]').content = lang === 'ar' ? 'ar_EG' : 'en_US';
    try { localStorage.setItem('vgo-language', lang); } catch (_) {}
    document.dispatchEvent(new CustomEvent('vgo:language'));
  }
  window.VGO_I18N = { apply: apply, t: function (key) { return window.VGO_DICTIONARY[lang][key] || key; } };
  document.querySelectorAll('[data-lang-btn]').forEach(function (btn) { btn.addEventListener('click', function () { apply(btn.dataset.langBtn); }); });
  apply(lang);
})();
''',encoding='utf-8')
